// Test-only recovery link generated by Auth Admin API, not an email delivery test.
const {chromium}=require(process.env.PLAYWRIGHT_MODULE||'playwright');
const {createClient}=require(process.env.SUPABASE_MODULE);
const fs=require('node:fs'),crypto=require('node:crypto'),assert=require('node:assert/strict');
(async()=>{
 const fixture=JSON.parse(fs.readFileSync(process.env.QA_AUTH_FILE,'utf8'));
 const b=await chromium.launch({channel:'msedge'}),p=await b.newPage({viewport:{width:1440,height:1000}});
 try{
  await p.goto(fixture.recoveryLink);await p.getByRole('heading',{name:'Nueva contraseña',exact:true}).waitFor({timeout:45000});
  await p.waitForFunction(()=>window.cozyCity?.snapshot().bankState==='OFFICE_IDLE');
  assert.equal(await p.locator('input[name=password]').getAttribute('autocomplete'),'new-password');
  assert.ok(!p.url().includes('access_token'));
  const session=await p.evaluate(async()=>{const {getSupabase}=await import('./finance/supabase-client.mjs');return (await (await getSupabase()).auth.getSession()).data.session;});
  const c=createClient('https://xnpavjonigaocypgrpoh.supabase.co','sb_publishable_VVwoB2e2MI2EG3RPcfabww_CeSJ_Dcl',{auth:{persistSession:false,autoRefreshToken:false}});
  assert.equal((await c.auth.setSession(session)).error,null);
  // Password changes use the API on an ephemeral QA identity, never a user's credential.
  const old=fixture.users[0].password,next=crypto.randomBytes(28).toString('base64url');
  assert.equal((await c.auth.updateUser({password:next})).error,null);
  await c.auth.signOut({scope:'local'});
  assert.ok((await c.auth.signInWithPassword({email:fixture.users[0].email,password:old})).error);
  assert.equal((await c.auth.signInWithPassword({email:fixture.users[0].email,password:next})).error,null);
  fixture.users[0].password=next;delete fixture.recoveryLink;fs.writeFileSync(process.env.QA_AUTH_FILE,JSON.stringify(fixture));await c.auth.signOut({scope:'local'});
  const results={passed:true,testedAt:new Date().toISOString(),checks:['Real single-use Auth recovery callback opens the office and password form','SDK removes credentials from URL','Password API update changes the credential; old password fails and new password logs in'],limitation:'Uses an Admin API generated recovery link; SMTP email delivery is verified separately.'};
  fs.writeFileSync('cozy/docs/qa/bank-mvp/auth-results.json',JSON.stringify(results,null,2));console.log(JSON.stringify(results,null,2));
 }finally{await b.close();}
})().catch(e=>{console.error(e.message);process.exitCode=1;});
